div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const availableColors = [
  { name: 'Emerald', hex: '#10b981' },
  { name: 'Amber', hex: '#f59e0b' },
  { name: 'Rose', hex: '#f43f5e' },
  { name: 'Purple', hex: '#a855f7' },
  { name: 'Cyan', hex: '#06b6d4' },
  { name: 'White', hex: '#ffffff' }
];

let selectedColor = availableColors[0].hex;
let highScore = parseInt(localStorage.getItem('flappy_square_high_score') || '0', 10);

let gameState = 'MENU'; // MENU, PLAYING, GAMEOVER
let animationFrameId;

// Player physics
const square = {
  x: 70,
  y: 250,
  size: 24,
  velocity: 0,
  gravity: 0.42,
  jumpStrength: -7.5
};

// Pipes
let pipes = [];
const pipeWidth = 52;
const pipeGap = 125;
const pipeSpeed = 2.4;
let spawnTimer = 0;
let currentScore = 0;

// UI Updates
document.getElementById('highScoreText').textContent = highScore;
document.getElementById('bestScoreDisplay').textContent = highScore;

// Build Color Selection Grid
const picker = document.getElementById('colorPicker');
availableColors.forEach((c, index) => {
  const swatch = document.createElement('div');
  swatch.className = `color-swatch ${index === 0 ? 'active' : ''}`;
  swatch.style.backgroundColor = c.hex;
  swatch.onclick = () => {
    document.querySelectorAll('.color-swatch').forEach(s => s.classList.remove('active'));
    swatch.classList.add('active');
    selectedColor = c.hex;
  };
  picker.appendChild(swatch);
});

function triggerJump() {
  if (gameState === 'PLAYING') {
    square.velocity = square.jumpStrength;
  }
}

// Controls: Spacebar & Click/Tap
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    e.preventDefault();
    if (gameState === 'PLAYING') triggerJump();
    else if (gameState === 'MENU' || gameState === 'GAMEOVER') startGame();
  }
});

canvas.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  if (gameState === 'PLAYING') triggerJump();
});

function openMenu() {
  gameState = 'MENU';
  document.getElementById('gameOverOverlay').style.display = 'none';
  document.getElementById('menuOverlay').style.display = 'flex';
  drawMenuPreview();
}

function startGame() {
  gameState = 'PLAYING';
  document.getElementById('menuOverlay').style.display = 'none';
  document.getElementById('gameOverOverlay').style.display = 'none';

  // Reset variables
  square.y = 250;
  square.velocity = 0;
  pipes = [];
  spawnTimer = 0;
  currentScore = 0;

  if (animationFrameId) cancelAnimationFrame(animationFrameId);
  gameLoop();
}

function spawnPipe() {
  const minHeight = 50;
  const maxHeight = canvas.height - pipeGap - minHeight;
  const topHeight = Math.floor(Math.random() * (maxHeight - minHeight + 1)) + minHeight;

  pipes.push({
    x: canvas.width,
    topHeight: topHeight,
    bottomY: topHeight + pipeGap,
    passed: false
  });
}

function gameOver() {
  gameState = 'GAMEOVER';
  if (currentScore > highScore) {
    highScore = currentScore;
    localStorage.setItem('flappy_square_high_score', highScore.toString());
    document.getElementById('highScoreText').textContent = highScore;
  }

  document.getElementById('finalScoreDisplay').textContent = currentScore;
  document.getElementById('bestScoreDisplay').textContent = highScore;
  document.getElementById('gameOverOverlay').style.display = 'flex';
}

function drawMenuPreview() {
  ctx.fillStyle = '#0284c7';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw preview ground
  ctx.fillStyle = '#0369a1';
  ctx.fillRect(0, canvas.height - 40, canvas.width, 40);
}

function gameLoop() {
  if (gameState !== 'PLAYING') return;

  // 1. Update Physics
  square.velocity += square.gravity;
  square.y += square.velocity;

  // Ground & Ceiling Collisions
  if (square.y + square.size >= canvas.height - 40 || square.y <= 0) {
    gameOver();
    return;
  }

  // 2. Spawn & Update Pipes
  spawnTimer++;
  if (spawnTimer > 100) {
    spawnPipe();
    spawnTimer = 0;
  }

  for (let i = pipes.length - 1; i >= 0; i--) {
    let p = pipes[i];
    p.x -= pipeSpeed;

    // Score increment
    if (!p.passed && p.x + pipeWidth < square.x) {
      p.passed = true;
      currentScore++;
    }

    // AABB Collision Detection
    const inPipeX = square.x + square.size > p.x && square.x < p.x + pipeWidth;
    const hitTopPipe = square.y < p.topHeight;
    const hitBottomPipe = square.y + square.size > p.bottomY;

    if (inPipeX && (hitTopPipe || hitBottomPipe)) {
      gameOver();
      return;
    }

    // Remove offscreen pipes
    if (p.x + pipeWidth < 0) {
      pipes.splice(i, 1);
    }
  }

  // 3. Render Canvas
  ctx.fillStyle = '#0284c7';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw Pipes
  pipes.forEach(p => {
    ctx.fillStyle = '#15803d'; // Pipe body
    ctx.fillRect(p.x, 0, pipeWidth, p.topHeight);
    ctx.fillRect(p.x, p.bottomY, pipeWidth, canvas.height - p.bottomY - 40);

    ctx.fillStyle = '#22c55e'; // Pipe rims
    ctx.fillRect(p.x - 3, p.topHeight - 16, pipeWidth + 6, 16);
    ctx.fillRect(p.x - 3, p.bottomY, pipeWidth + 6, 16);
  });

  // Draw Ground
  ctx.fillStyle = '#0369a1';
  ctx.fillRect(0, canvas.height - 40, canvas.width, 40);
  ctx.fillStyle = '#22c55e';
  ctx.fillRect(0, canvas.height - 40, canvas.width, 6);

  // Draw Player Square
  ctx.fillStyle = selectedColor;
  ctx.fillRect(square.x, square.y, square.size, square.size);
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.strokeRect(square.x, square.y, square.size, square.size);

  // Draw Current Live Score
  ctx.fillStyle = '#ffffff';
  ctx.font = '900 32px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(currentScore.toString(), canvas.width / 2, 60);

  animationFrameId = requestAnimationFrame(gameLoop);
}

// Initial draw
drawMenuPreview();
